import java.time.OffsetDateTime;
import java.util.List;

public record Item(
        long productId,
        String title,
        long quantity,
        double unitPrice
) {
}

public record Order(
        String orderId,
        OffsetDateTime placedAt,
        List<Item> items,
        List<String> tags,
        Object coupon
) {
}

public class Item
{
    public required long ProductId { get; set; }
    public required string Title { get; set; }
    public required long Quantity { get; set; }
    public required double UnitPrice { get; set; }
}

public class Order
{
    public required string OrderId { get; set; }
    public required DateTime PlacedAt { get; set; }
    public required List<Item> Items { get; set; }
    public required List<string> Tags { get; set; }
    public object? Coupon { get; set; }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "Order",
  "type": "object",
  "properties": {
    "orderId": {
      "type": "string"
    },
    "placedAt": {
      "type": "string",
      "format": "date-time"
    },
    "items": {
      "type": "array",
      "items": {
        "$ref": "#/$defs/Item"
      }
    },
    "tags": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "coupon": {
      "oneOf": [
        {},
        {
          "type": "null"
        }
      ]
    }
  },
  "required": [
    "orderId",
    "placedAt",
    "items",
    "tags",
    "coupon"
  ],
  "$defs": {
    "Item": {
      "type": "object",
      "properties": {
        "productId": {
          "type": "integer"
        },
        "title": {
          "type": "string"
        },
        "quantity": {
          "type": "integer"
        },
        "unitPrice": {
          "type": "number"
        }
      },
      "required": [
        "productId",
        "title",
        "quantity",
        "unitPrice"
      ]
    }
  }
}

export interface Item {
  productId: number
  title: string
  quantity: number
  unitPrice: number
}

export interface Order {
  orderId: string
  placedAt: Date
  items: Item[]
  tags: string[]
  coupon: unknown | null
}

